document.addEventListener("DOMContentLoaded",(function(){const pageContent=document.getElementById("page-content"),navLinks=document.querySelectorAll(".nav-link"),activeColor="#fd7e14",inactiveColor="gray";function updateNavState(page){navLinks.forEach((link=>{const icon=link.querySelector("i"),text=link.querySelector("p");icon&&(icon.style.color=inactiveColor),text&&(text.style.color=inactiveColor)}));const activeItem=document.querySelector(`.nav-link.${page}`);if(activeItem){const icon=activeItem.querySelector("i"),text=activeItem.querySelector("p");icon&&(icon.style.color=activeColor),text&&(text.style.color=activeColor)}}function loadPage(page){localStorage.setItem("currentPage",page),updateNavState(page),pageContent.innerHTML='<div class="text-center text-orange-400 py-4 h-screen flex items-center justify-center"><i class="fas fa-spinner fa-spin fa-3x"></i><p class="ml-3">Loading...</p></div>';const loadingStartTime=Date.now();fetch(`./${page}/index.php`).then((response=>{if(!response.ok)throw new Error(`HTTP error! Status: ${response.status}`);return response.text()})).then((data=>{const fetchTime=Date.now()-loadingStartTime,remainingTime=Math.max(0,500-fetchTime);setTimeout((()=>{pageContent.innerHTML=data,pageContent.querySelectorAll("script").forEach((oldScript=>{const newScript=document.createElement("script");Array.from(oldScript.attributes).forEach((attr=>{newScript.setAttribute(attr.name,attr.value)})),newScript.textContent=oldScript.textContent,oldScript.parentNode.replaceChild(newScript,oldScript)})),"explore"!=page&&updateNavState(page)}),remainingTime)})).catch((error=>{console.error("Error loading page:",error);const fetchTime=Date.now()-loadingStartTime,remainingTime=Math.max(0,500-fetchTime);setTimeout((()=>{pageContent.innerHTML='\n            <div class="text-center py-4 mt-36">\n                <i class="fas fa-exclamation-triangle text-red-500 text-4xl mb-3"></i>\n                <p class="text-gray-700">An error occurred while loading the page. Please try again.</p>\n                <button class="mt-3 px-4 py-2 bg-orange-500 text-white rounded" \n                        onclick="loadPage(\'explore\')">Return to Explore</button>\n            </div>\n        '}),remainingTime)}))}loadPage(localStorage.getItem("currentPage")||"explore"),navLinks.forEach((link=>{link.addEventListener("click",(function(){const page=this.getAttribute("data-page");page&&loadPage(page)}))})),window.loadPage=loadPage}));